"""No research seeds are generated by these routing-only tests."""
import json,tempfile,unittest
from pathlib import Path
from types import SimpleNamespace
from unittest.mock import patch
from src.fast_exact import FastLibrary,FastEvaluator
from src.fast_runner import run_paired_fast
from src.smoke_authorization import authorize,PILOT,CONFIRM,sha256_file

class PilotRouteTests(unittest.TestCase):
    def test_preparation_never_executable(self):
        with self.assertRaises(ValueError):FastLibrary.from_graph(scope='pilot-preparation')

    def test_pilot_scope_reaches_native_snapshot_verifier(self):
        with patch('src.smoke_authorization.authorize',return_value={}), patch('src.execution_snapshot.verify_snapshot',side_effect=ValueError('verified scope reached')):
            with self.assertRaisesRegex(ValueError,'verified scope reached'):FastLibrary.from_graph(scope='pilot-execution')

    def test_pilot_routes_authorize_before_data(self):
        with patch('src.smoke_authorization.authorize',side_effect=PermissionError('AUTHORIZATION_DENIED')) as gate:
            with self.assertRaises(PermissionError):FastLibrary.from_graph(scope='pilot-execution')
            with self.assertRaises(PermissionError):FastEvaluator(SimpleNamespace(namespace=PILOT),None)
            with self.assertRaises(PermissionError):run_paired_fast(json.dumps({'namespace':PILOT}),None)
            self.assertEqual(gate.call_count,3)
        with self.assertRaises(RuntimeError):FastEvaluator(SimpleNamespace(namespace=CONFIRM),None)

    def test_flag_change_only_enables_authorizer(self):
        with tempfile.TemporaryDirectory() as td:
            snap=Path(td)/'snapshot.json';snap.write_text(json.dumps({'execution_scope':'pilot-execution'}))
            auth=Path(td)/'authorization.json'; state={'authorization_version':1,'namespace_authorizations':{'PILOT':{'allowed':False,'required_snapshot_sha256':sha256_file(snap)},'CONFIRM':{'allowed':False}}}
            auth.write_text(json.dumps(state))
            with patch('src.smoke_authorization.verify_snapshot'):
                with self.assertRaises(PermissionError):authorize(PILOT,snap,auth)
                before=snap.read_bytes();state['authorization_version']=2
                state['namespace_authorizations']['PILOT']['allowed']=True;auth.write_text(json.dumps(state))
                self.assertEqual(authorize(PILOT,snap,auth)['authorization_version'],2)
                self.assertEqual(snap.read_bytes(),before)
                with self.assertRaises(PermissionError):authorize(CONFIRM,snap,auth)

    def test_denied_common_route_never_calls_seed_or_instance_generator(self):
        from src.experiment_orchestrator import run_experiment
        with tempfile.TemporaryDirectory() as td:
            snap=Path(td)/'snapshot.json';snap.write_text(json.dumps({'execution_scope':'pilot-execution'}))
            auth=Path(td)/'authorization.json'
            state={'authorization_version':1,'namespace_authorizations':{'PILOT':{'allowed':False,'required_snapshot_sha256':sha256_file(snap)},'CONFIRM':{'allowed':False}}}
            auth.write_text(json.dumps(state));out=Path(td)/'research_output'
            with patch('src.smoke_authorization.verify_snapshot'), \
                 patch('src.instances.derive_seed') as seed, \
                 patch('src.instances.generate_instance') as instance:
                with self.assertRaisesRegex(PermissionError,'AUTHORIZATION_DENIED'):
                    run_experiment({},PILOT,snap,auth,output_root=out)
                seed.assert_not_called();instance.assert_not_called()
                self.assertFalse(out.exists())
                with self.assertRaises(PermissionError):
                    run_experiment({},CONFIRM,snap,auth,output_root=out)
                seed.assert_not_called();instance.assert_not_called()
                self.assertFalse(out.exists())

if __name__=='__main__':unittest.main()
